func (a *App) deleteReport(w http.ResponseWriter, r *http.Request) {
	id, ok := pathID(w, r)
	if !ok {
		return
	}
	p := currentPrincipal(r.Context())
	version, err := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("version")))
